INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published)
VALUES ('2025-12-31-thailand-the-incentive-that-drove-adoption-runs-out', '2025-12-31', '2025-12', 'Royal Decree No. 766 gave a double deduction for e-Tax Invoice and e-Withholding Tax investment. It reached its end date without a renewal in place — and in a country with no mandate, the incentive was the whole engine.', '<h3>🇹🇭 Thailand''s 200% e-invoicing deduction runs out</h3><p>Royal Decree No. 766 expires today. Since 1 January 2023 it had allowed a double deduction — the ordinary 100 per cent plus a further 100 — against corporate income tax for investment in e-Tax Invoice, e-Receipt and e-Withholding Tax systems, covering hardware, software and service-provider fees. It replaced Decree No. 718, which had run to the end of 2022, so the relief had been continuous for three years.</p><p>In most countries this would be a footnote. In Thailand it is the main event, because <strong>Thailand has no e-invoicing mandate at all</strong> and never has. Both routes — the full XML system and the lighter e-mail route for businesses under 30 million baht of revenue — are voluntary in the words of their own instruments. Clause 12 of the governing Director-General announcement lets a registrant choose electronic or paper form transaction by transaction, and withdraw entirely on a form.</p><p>Where there is no obligation, adoption runs on incentive. Removing the incentive without replacing it removes the reason. Anyone planning a Thai e-invoicing investment in the new year should price it without the deduction until something says otherwise.</p>', 'https://www.rd.go.th/1603.html', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2025-12-31-thailand-the-incentive-that-drove-adoption-runs-out', id FROM countries WHERE code = 'TH';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2025-12-31-thailand-the-incentive-that-drove-adoption-runs-out', 'en', '🇹🇭 Thailand''s 200% e-invoicing deduction runs out', 'Royal Decree No. 766 gave a double deduction for e-Tax Invoice and e-Withholding Tax investment. It reached its end date without a renewal in place — and in a country with no mandate, the incentive was the whole engine.', '<h3>🇹🇭 Thailand''s 200% e-invoicing deduction runs out</h3><p>Royal Decree No. 766 expires today. Since 1 January 2023 it had allowed a double deduction — the ordinary 100 per cent plus a further 100 — against corporate income tax for investment in e-Tax Invoice, e-Receipt and e-Withholding Tax systems, covering hardware, software and service-provider fees. It replaced Decree No. 718, which had run to the end of 2022, so the relief had been continuous for three years.</p><p>In most countries this would be a footnote. In Thailand it is the main event, because <strong>Thailand has no e-invoicing mandate at all</strong> and never has. Both routes — the full XML system and the lighter e-mail route for businesses under 30 million baht of revenue — are voluntary in the words of their own instruments. Clause 12 of the governing Director-General announcement lets a registrant choose electronic or paper form transaction by transaction, and withdraw entirely on a form.</p><p>Where there is no obligation, adoption runs on incentive. Removing the incentive without replacing it removes the reason. Anyone planning a Thai e-invoicing investment in the new year should price it without the deduction until something says otherwise.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2025-12-31-thailand-the-incentive-that-drove-adoption-runs-out', 'es', '🇹🇭 Vence la deducción tailandesa del 200 % por factura electrónica', 'El Decreto Real n.º 766 concedía una doble deducción por invertir en factura y retención electrónicas. Llegó a su fecha final sin relevo, y en un país sin obligación el incentivo era todo el motor.', '<h3>🇹🇭 Vence la deducción tailandesa del 200 % por factura electrónica</h3><p>El Decreto Real n.º 766 expira hoy. Desde el 1 de enero de 2023 permitía una doble deducción —el 100 % ordinario más otro 100— en el impuesto de sociedades por invertir en sistemas de factura electrónica, recibo electrónico y retención electrónica, incluidos equipos, programas y honorarios de proveedores. Sustituyó al Decreto n.º 718, vigente hasta finales de 2022, de modo que el beneficio había sido continuo durante tres años.</p><p>En la mayoría de los países esto sería una nota al pie. En Tailandia es lo principal, porque <strong>Tailandia no tiene obligación alguna de factura electrónica</strong>, ni la ha tenido nunca. Ambas vías —el sistema XML completo y la más ligera por correo para empresas de menos de 30 millones de baht— son voluntarias según sus propios instrumentos. La cláusula 12 del anuncio que las rige permite elegir electrónico o papel operación por operación, y darse de baja con un formulario.</p><p>Donde no hay obligación, la adopción se mueve por incentivo. Retirar el incentivo sin sustituirlo retira el motivo. Quien planifique una inversión tailandesa en el nuevo año debería presupuestarla sin la deducción mientras nada diga lo contrario.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2025-12-31-thailand-the-incentive-that-drove-adoption-runs-out', 'de', '🇹🇭 Thailands 200-Prozent-Abzug für E-Rechnungen läuft aus', 'Das Königliche Dekret Nr. 766 gewährte einen doppelten Abzug für Investitionen in E-Rechnung und E-Quellensteuer. Es erreichte sein Enddatum ohne Nachfolger — und in einem Land ohne Pflicht war der Anreiz der ganze Motor.', '<h3>🇹🇭 Thailands 200-Prozent-Abzug für E-Rechnungen läuft aus</h3><p>Das Königliche Dekret Nr. 766 endet heute. Seit dem 1. Januar 2023 erlaubte es einen doppelten Abzug — die gewöhnlichen 100 Prozent und weitere 100 — von der Körperschaftsteuer für Investitionen in E-Rechnungs-, E-Quittungs- und E-Quellensteuersysteme, einschliesslich Hardware, Software und Dienstleisterhonoraren. Es löste Dekret Nr. 718 ab, das bis Ende 2022 galt; die Entlastung bestand also drei Jahre ununterbrochen.</p><p>In den meisten Ländern wäre das eine Fussnote. In Thailand ist es die Hauptsache, denn <strong>Thailand kennt überhaupt keine E-Rechnungspflicht</strong> und kannte nie eine. Beide Wege — das volle XML-System und der leichtere E-Mail-Weg für Unternehmen unter 30 Millionen Baht Umsatz — sind nach dem Wortlaut ihrer eigenen Instrumente freiwillig. Ziffer 12 der massgeblichen Bekanntmachung lässt die Wahl je Geschäftsvorfall und den vollständigen Austritt per Formular.</p><p>Wo keine Pflicht besteht, trägt der Anreiz die Einführung. Den Anreiz ersatzlos zu streichen, streicht den Grund. Wer im neuen Jahr eine thailändische Investition plant, sollte sie ohne den Abzug kalkulieren, solange nichts anderes gilt.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2025-12-31-thailand-the-incentive-that-drove-adoption-runs-out', 'fr', '🇹🇭 La déduction thaïlandaise de 200 % pour la facture électronique expire', 'Le décret royal n° 766 accordait une double déduction pour l''investissement en facture et retenue électroniques. Il a atteint son terme sans relais — et dans un pays sans obligation, l''incitation était tout le moteur.', '<h3>🇹🇭 La déduction thaïlandaise de 200 % pour la facture électronique expire</h3><p>Le décret royal n° 766 prend fin aujourd''hui. Depuis le 1er janvier 2023, il autorisait une double déduction — les 100 % ordinaires et 100 de plus — à l''impôt sur les sociétés pour l''investissement dans les systèmes de facture électronique, de reçu électronique et de retenue à la source électronique, matériel, logiciels et honoraires compris. Il succédait au décret n° 718, en vigueur jusqu''à fin 2022 : l''allègement était donc continu depuis trois ans.</p><p>Dans la plupart des pays, ce serait une note de bas de page. En Thaïlande, c''est l''essentiel, car <strong>la Thaïlande n''a aucune obligation de facturation électronique</strong> et n''en a jamais eu. Les deux voies — le système XML complet et la voie par courriel pour les entreprises sous 30 millions de bahts — sont volontaires selon leurs propres instruments. La clause 12 de l''annonce qui les régit laisse choisir opération par opération, et se retirer par simple formulaire.</p><p>Là où il n''y a pas d''obligation, c''est l''incitation qui porte l''adoption. Supprimer l''incitation sans la remplacer supprime la raison. Qui prévoit un investissement thaïlandais l''an prochain devrait le chiffrer sans la déduction tant que rien ne dit le contraire.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published)
VALUES ('2026-06-16-thailand-cabinet-approves-a-replacement-not-yet-a-law', '2026-06-16', '2026-06', 'The Cabinet approved two more years of the 200 per cent deduction for 2026 and 2027, plus a cut in e-Withholding Tax to a flat 1 per cent. Two months on, no enacting Royal Decree has appeared.', '<h3>🇹🇭 Thailand approves a replacement incentive — which is not yet law</h3><p>The Revenue Department announced today, in press release 14/2569, that the Cabinet has approved a two-year extension of the 200 per cent deduction for investment in e-Tax Invoice and e-Withholding Tax systems, covering 2026 and 2027. The scope is slightly wider than before: it now includes the cost of information-system assessment services submitted to <strong>ETDA</strong>. The same measure cuts e-Withholding Tax rates from 5, 3 and 2 per cent to a flat 1 per cent over the same two years.</p><p>The gap is the story. Royal Decree No. 766 lapsed on 31 December 2025, so the relief has been absent since the start of the year, and Cabinet approval is not enactment. <strong>As at 27 August 2026, no implementing Royal Decree appears on the Revenue Department''s own decree index</strong>, whose most recent entries are numbers 802 to 807 — none of them this measure. Businesses investing during 2026 are relying on an approved but unpromulgated relief.</p><p>One detail worth carrying: the Government PR Department''s account of the same Cabinet decision names DEPA as the assessment body, where the Revenue Department names ETDA. Where two arms of the same government disagree about who assesses your system, follow the one that administers the tax.</p><p>Watch the decree index rather than the press release. An approval is not a rule until something is promulgated.</p>', 'https://www.rd.go.th/fileadmin/user_upload/news/2569thai/news14_2569.pdf', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-06-16-thailand-cabinet-approves-a-replacement-not-yet-a-law', id FROM countries WHERE code = 'TH';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-06-16-thailand-cabinet-approves-a-replacement-not-yet-a-law', 'en', '🇹🇭 Thailand approves a replacement incentive — which is not yet law', 'The Cabinet approved two more years of the 200 per cent deduction for 2026 and 2027, plus a cut in e-Withholding Tax to a flat 1 per cent. Two months on, no enacting Royal Decree has appeared.', '<h3>🇹🇭 Thailand approves a replacement incentive — which is not yet law</h3><p>The Revenue Department announced today, in press release 14/2569, that the Cabinet has approved a two-year extension of the 200 per cent deduction for investment in e-Tax Invoice and e-Withholding Tax systems, covering 2026 and 2027. The scope is slightly wider than before: it now includes the cost of information-system assessment services submitted to <strong>ETDA</strong>. The same measure cuts e-Withholding Tax rates from 5, 3 and 2 per cent to a flat 1 per cent over the same two years.</p><p>The gap is the story. Royal Decree No. 766 lapsed on 31 December 2025, so the relief has been absent since the start of the year, and Cabinet approval is not enactment. <strong>As at 27 August 2026, no implementing Royal Decree appears on the Revenue Department''s own decree index</strong>, whose most recent entries are numbers 802 to 807 — none of them this measure. Businesses investing during 2026 are relying on an approved but unpromulgated relief.</p><p>One detail worth carrying: the Government PR Department''s account of the same Cabinet decision names DEPA as the assessment body, where the Revenue Department names ETDA. Where two arms of the same government disagree about who assesses your system, follow the one that administers the tax.</p><p>Watch the decree index rather than the press release. An approval is not a rule until something is promulgated.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-06-16-thailand-cabinet-approves-a-replacement-not-yet-a-law', 'es', '🇹🇭 Tailandia aprueba un incentivo de reemplazo que aún no es ley', 'El Consejo de Ministros aprobó dos años más de la deducción del 200 % para 2026 y 2027, y una rebaja de la retención electrónica a un 1 % único. Dos meses después no ha aparecido decreto real alguno.', '<h3>🇹🇭 Tailandia aprueba un incentivo de reemplazo que aún no es ley</h3><p>El Departamento de Hacienda anunció hoy, en la nota 14/2569, que el Consejo de Ministros ha aprobado una prórroga de dos años de la deducción del 200 % por invertir en sistemas de factura electrónica y retención electrónica, para 2026 y 2027. El alcance es algo más amplio que antes: incluye ahora el coste de los servicios de evaluación de sistemas presentados a <strong>ETDA</strong>. La misma medida rebaja la retención electrónica del 5, 3 y 2 por ciento a un 1 por ciento único durante esos dos años.</p><p>La noticia es el hueco. El Decreto Real n.º 766 venció el 31 de diciembre de 2025, así que el beneficio falta desde principios de año, y la aprobación del Consejo no es promulgación. <strong>A 27 de agosto de 2026 no consta decreto real de desarrollo en el índice del propio Departamento</strong>, cuyas entradas más recientes son los números 802 a 807, ninguno de ellos esta medida. Quien invierta durante 2026 se apoya en un beneficio aprobado pero no promulgado.</p><p>Un detalle que conviene llevarse: el Departamento de Información del Gobierno, al relatar la misma decisión, nombra a DEPA como organismo evaluador donde Hacienda nombra a ETDA. Cuando dos brazos del mismo gobierno discrepan sobre quién evalúa su sistema, siga al que administra el impuesto.</p><p>Vigile el índice de decretos y no la nota de prensa. Una aprobación no es una norma hasta que algo se promulga.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-06-16-thailand-cabinet-approves-a-replacement-not-yet-a-law', 'de', '🇹🇭 Thailand billigt einen Ersatzanreiz, der noch kein Recht ist', 'Das Kabinett billigte zwei weitere Jahre des 200-Prozent-Abzugs für 2026 und 2027 sowie eine Senkung der E-Quellensteuer auf einheitlich 1 Prozent. Zwei Monate später ist kein umsetzendes Dekret erschienen.', '<h3>🇹🇭 Thailand billigt einen Ersatzanreiz, der noch kein Recht ist</h3><p>Die Steuerbehörde gab heute in der Mitteilung 14/2569 bekannt, dass das Kabinett eine zweijährige Verlängerung des 200-Prozent-Abzugs für Investitionen in E-Rechnungs- und E-Quellensteuersysteme für 2026 und 2027 gebilligt hat. Der Umfang ist etwas weiter als zuvor: erfasst sind nun auch die Kosten von Systemprüfungsleistungen, die bei <strong>ETDA</strong> eingereicht werden. Dieselbe Massnahme senkt die E-Quellensteuersätze von 5, 3 und 2 Prozent auf einheitlich 1 Prozent für dieselben zwei Jahre.</p><p>Die Nachricht ist die Lücke. Das Königliche Dekret Nr. 766 lief am 31. Dezember 2025 aus, die Entlastung fehlt also seit Jahresbeginn, und eine Kabinettsbilligung ist keine Verkündung. <strong>Am 27. August 2026 findet sich im Dekretverzeichnis der Behörde kein umsetzendes Dekret</strong>; die jüngsten Einträge sind die Nummern 802 bis 807, keiner davon diese Massnahme. Wer 2026 investiert, verlässt sich auf eine gebilligte, aber nicht verkündete Entlastung.</p><p>Ein Detail zum Mitnehmen: Das Regierungspresseamt nennt in seiner Darstellung derselben Entscheidung DEPA als Prüfstelle, wo die Steuerbehörde ETDA nennt. Wenn zwei Arme derselben Regierung uneins sind, wer Ihr System prüft, folgen Sie dem, der die Steuer verwaltet.</p><p>Beobachten Sie das Dekretverzeichnis, nicht die Pressemitteilung. Eine Billigung ist keine Regel, bis etwas verkündet ist.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-06-16-thailand-cabinet-approves-a-replacement-not-yet-a-law', 'fr', '🇹🇭 La Thaïlande approuve une incitation de remplacement qui n''est pas encore la loi', 'Le Conseil des ministres a approuvé deux ans de plus de la déduction de 200 % pour 2026 et 2027, ainsi qu''une retenue électronique ramenée à 1 % uniforme. Deux mois plus tard, aucun décret royal n''est paru.', '<h3>🇹🇭 La Thaïlande approuve une incitation de remplacement qui n''est pas encore la loi</h3><p>L''administration fiscale a annoncé aujourd''hui, dans le communiqué 14/2569, que le Conseil des ministres a approuvé une prorogation de deux ans de la déduction de 200 % pour l''investissement dans les systèmes de facture électronique et de retenue à la source électronique, au titre de 2026 et 2027. Le champ est un peu plus large qu''auparavant : il couvre désormais le coût des services d''évaluation de systèmes soumis à l''<strong>ETDA</strong>. La même mesure ramène les taux de retenue électronique de 5, 3 et 2 % à 1 % uniforme sur les deux mêmes années.</p><p>L''information, c''est le vide. Le décret royal n° 766 a expiré le 31 décembre 2025 : l''allègement manque donc depuis le début de l''année, et une approbation du Conseil n''est pas une promulgation. <strong>Au 27 août 2026, aucun décret royal d''application ne figure à l''index de l''administration</strong>, dont les entrées les plus récentes sont les numéros 802 à 807, aucun n''étant cette mesure. Les entreprises qui investissent en 2026 s''appuient sur un allègement approuvé mais non promulgué.</p><p>Un détail à retenir : le service de presse du gouvernement, relatant la même décision, nomme la DEPA comme organisme d''évaluation là où l''administration fiscale nomme l''ETDA. Quand deux bras du même gouvernement divergent sur qui évalue votre système, suivez celui qui administre l''impôt.</p><p>Surveillez l''index des décrets, non le communiqué. Une approbation n''est pas une règle tant que rien n''est promulgué.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published)
VALUES ('2026-08-27-thailand-a-third-mandate-that-was-never-enacted', '2026-08-27', '2026-08', 'A vendor page dated six days ago describes phased mandatory e-invoicing in Thailand, with a THB 1.8 billion threshold and a standard called RD STD 03-2566. None of it exists — and the threshold looks like a thousand-fold misprint.', '<h3>🇹🇭 A third published Thai mandate that was never enacted</h3><p>A compliance vendor''s Thailand page, dated 21 August 2026, sets out a phased mandate: large taxpayers from 2024, then businesses with revenue above <strong>THB 1.8 billion</strong> from January 2025, under a standard it calls <strong>RD STD 03-2566</strong>. Elsewhere on the same page it states that the regime remains voluntary.</p><p>The second statement is correct and the first is invented. There are no phases. There is no such threshold. There is no such standard — the real one is ETDA recommendation ขมธอ. 3-2560, published in January 2017 and based on the UN/CEFACT Cross Industry Invoice model rather than UBL. And the Thai instruments are not ambiguous: clause 12 of Director-General Announcement No. 15 lets a registrant choose electronic or paper form for each transaction, and withdraw entirely on form บ.อ.09.</p><p>The threshold is the tell. Thailand''s VAT registration threshold is <strong>1.8 million baht</strong>. The published figure is the same number inflated by a factor of a thousand, attached to a mandate that does not exist — in the one figure that would decide whether a business is in scope.</p><p>This is the third such page we have had to contradict this month. A dozen vendors still publish a March 2026 Botswana mandate that never happened, tracing to one conditional line in a budget speech. Another records Hong Kong''s e-Procurement System as compulsory when two government pages say it is optional. The pattern is consistent: a plausible date, a confident tone, no primary citation, and nobody revisiting it. When a page tells you a country has a mandate, the question to ask is which instrument says so.</p>', 'https://www.rd.go.th/fileadmin/user_upload/kormor/newlaw/dgg15.pdf', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-08-27-thailand-a-third-mandate-that-was-never-enacted', id FROM countries WHERE code = 'TH';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-08-27-thailand-a-third-mandate-that-was-never-enacted', 'en', '🇹🇭 A third published Thai mandate that was never enacted', 'A vendor page dated six days ago describes phased mandatory e-invoicing in Thailand, with a THB 1.8 billion threshold and a standard called RD STD 03-2566. None of it exists — and the threshold looks like a thousand-fold misprint.', '<h3>🇹🇭 A third published Thai mandate that was never enacted</h3><p>A compliance vendor''s Thailand page, dated 21 August 2026, sets out a phased mandate: large taxpayers from 2024, then businesses with revenue above <strong>THB 1.8 billion</strong> from January 2025, under a standard it calls <strong>RD STD 03-2566</strong>. Elsewhere on the same page it states that the regime remains voluntary.</p><p>The second statement is correct and the first is invented. There are no phases. There is no such threshold. There is no such standard — the real one is ETDA recommendation ขมธอ. 3-2560, published in January 2017 and based on the UN/CEFACT Cross Industry Invoice model rather than UBL. And the Thai instruments are not ambiguous: clause 12 of Director-General Announcement No. 15 lets a registrant choose electronic or paper form for each transaction, and withdraw entirely on form บ.อ.09.</p><p>The threshold is the tell. Thailand''s VAT registration threshold is <strong>1.8 million baht</strong>. The published figure is the same number inflated by a factor of a thousand, attached to a mandate that does not exist — in the one figure that would decide whether a business is in scope.</p><p>This is the third such page we have had to contradict this month. A dozen vendors still publish a March 2026 Botswana mandate that never happened, tracing to one conditional line in a budget speech. Another records Hong Kong''s e-Procurement System as compulsory when two government pages say it is optional. The pattern is consistent: a plausible date, a confident tone, no primary citation, and nobody revisiting it. When a page tells you a country has a mandate, the question to ask is which instrument says so.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-08-27-thailand-a-third-mandate-that-was-never-enacted', 'es', '🇹🇭 Una tercera obligación tailandesa publicada que nunca se promulgó', 'Una página de proveedor de hace seis días describe una obligación por fases en Tailandia, con un umbral de 1.800 millones de baht y un estándar llamado RD STD 03-2566. Nada de ello existe, y el umbral parece una errata de factor mil.', '<h3>🇹🇭 Una tercera obligación tailandesa publicada que nunca se promulgó</h3><p>La página sobre Tailandia de un proveedor de cumplimiento, fechada el 21 de agosto de 2026, expone una obligación por fases: grandes contribuyentes desde 2024 y después empresas con ingresos superiores a <strong>1.800 millones de baht</strong> desde enero de 2025, bajo un estándar que llama <strong>RD STD 03-2566</strong>. En otro punto de la misma página afirma que el régimen sigue siendo voluntario.</p><p>La segunda afirmación es correcta y la primera es inventada. No hay fases. No existe tal umbral. No existe tal estándar: el real es la recomendación ขมธอ. 3-2560 de ETDA, publicada en enero de 2017 y basada en el modelo Cross Industry Invoice de UN/CEFACT y no en UBL. Y los instrumentos tailandeses no son ambiguos: la cláusula 12 del anuncio n.º 15 del Director General permite elegir electrónico o papel en cada operación, y darse de baja con el formulario บ.อ.09.</p><p>El umbral lo delata. El umbral de registro del IVA en Tailandia es de <strong>1,8 millones de baht</strong>. La cifra publicada es el mismo número multiplicado por mil, adherido a una obligación inexistente, y precisamente en la cifra que decidiría a quién alcanza.</p><p>Es la tercera página de este tipo que hemos tenido que contradecir este mes. Una docena de proveedores siguen publicando una obligación botsuanesa de marzo de 2026 que nunca ocurrió, trazable a una línea condicional de un discurso presupuestario. Otra recoge como obligatorio el sistema de contratación electrónica de Hong Kong cuando dos páginas oficiales dicen que es opcional. El patrón es constante: una fecha verosímil, un tono seguro, ninguna cita primaria y nadie que lo revise. Cuando una página le diga que un país tiene obligación, pregunte qué instrumento lo dice.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-08-27-thailand-a-third-mandate-that-was-never-enacted', 'de', '🇹🇭 Eine dritte veröffentlichte thailändische Pflicht, die nie erlassen wurde', 'Eine sechs Tage alte Anbieterseite beschreibt eine stufenweise Pflicht in Thailand, mit einer Schwelle von 1,8 Milliarden Baht und einem Standard namens RD STD 03-2566. Nichts davon existiert — und die Schwelle wirkt wie ein Druckfehler um den Faktor tausend.', '<h3>🇹🇭 Eine dritte veröffentlichte thailändische Pflicht, die nie erlassen wurde</h3><p>Die Thailand-Seite eines Compliance-Anbieters, datiert auf den 21. August 2026, legt eine stufenweise Pflicht dar: Grosssteuerpflichtige ab 2024, dann Unternehmen mit einem Umsatz über <strong>1,8 Milliarden Baht</strong> ab Januar 2025, nach einem Standard, den sie <strong>RD STD 03-2566</strong> nennt. An anderer Stelle derselben Seite heisst es, das Regime bleibe freiwillig.</p><p>Die zweite Aussage stimmt, die erste ist erfunden. Es gibt keine Stufen. Es gibt diese Schwelle nicht. Es gibt diesen Standard nicht — der wirkliche ist die ETDA-Empfehlung ขมธอ. 3-2560 vom Januar 2017, die auf dem UN/CEFACT-Modell Cross Industry Invoice beruht und nicht auf UBL. Und die thailändischen Instrumente sind eindeutig: Ziffer 12 der Bekanntmachung Nr. 15 des Generaldirektors lässt je Geschäftsvorfall die Wahl zwischen elektronisch und Papier und den vollständigen Austritt per Formular บ.อ.09.</p><p>Die Schwelle verrät es. Thailands MWST-Registrierungsschwelle beträgt <strong>1,8 Millionen Baht</strong>. Die veröffentlichte Zahl ist dieselbe, tausendfach vergrössert, angehängt an eine Pflicht, die es nicht gibt — und zwar an genau der Zahl, die über den Anwendungsbereich entscheiden würde.</p><p>Es ist die dritte solche Seite, der wir in diesem Monat widersprechen mussten. Ein Dutzend Anbieter veröffentlichen noch immer eine botsuanische Pflicht ab März 2026, die es nie gab und die auf eine bedingte Zeile in einer Budgetrede zurückgeht. Eine andere führt Hongkongs e-Procurement-System als verpflichtend, während zwei amtliche Seiten es als freiwillig bezeichnen. Das Muster ist gleich: ein plausibles Datum, ein sicherer Ton, keine Primärquelle und niemand, der es nachprüft. Sagt Ihnen eine Seite, ein Land habe eine Pflicht, lautet die Frage: welches Instrument sagt das?</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html)
VALUES ('2026-08-27-thailand-a-third-mandate-that-was-never-enacted', 'fr', '🇹🇭 Une troisième obligation thaïlandaise publiée qui n''a jamais été édictée', 'Une page d''éditeur vieille de six jours décrit une obligation par phases en Thaïlande, avec un seuil de 1,8 milliard de bahts et une norme nommée RD STD 03-2566. Rien de tout cela n''existe — et le seuil ressemble à une coquille d''un facteur mille.', '<h3>🇹🇭 Une troisième obligation thaïlandaise publiée qui n''a jamais été édictée</h3><p>La page Thaïlande d''un éditeur de conformité, datée du 21 août 2026, expose une obligation par phases : grands contribuables dès 2024, puis entreprises réalisant plus de <strong>1,8 milliard de bahts</strong> de recettes dès janvier 2025, sous une norme qu''elle nomme <strong>RD STD 03-2566</strong>. Ailleurs sur la même page, elle indique que le régime demeure volontaire.</p><p>La seconde affirmation est exacte et la première est inventée. Il n''y a pas de phases. Ce seuil n''existe pas. Cette norme n''existe pas — la vraie est la recommandation ETDA ขมธอ. 3-2560, publiée en janvier 2017 et fondée sur le modèle Cross Industry Invoice de l''UN/CEFACT, non sur UBL. Et les instruments thaïlandais ne sont pas ambigus : la clause 12 de l''annonce n° 15 du Directeur général laisse choisir entre électronique et papier pour chaque opération, et se retirer par le formulaire บ.อ.09.</p><p>Le seuil trahit l''erreur. Le seuil d''assujettissement à la TVA en Thaïlande est de <strong>1,8 million de bahts</strong>. Le chiffre publié est le même, multiplié par mille, accroché à une obligation qui n''existe pas — et précisément sur le chiffre qui déciderait du champ d''application.</p><p>C''est la troisième page de ce genre que nous devons contredire ce mois-ci. Une douzaine d''éditeurs publient encore une obligation botswanaise de mars 2026 qui n''a jamais eu lieu, remontant à une ligne conditionnelle d''un discours budgétaire. Une autre présente comme obligatoire le système e-Procurement de Hong Kong quand deux pages officielles le disent facultatif. Le schéma est constant : une date plausible, un ton assuré, aucune citation primaire, et personne pour y revenir. Quand une page vous dit qu''un pays a une obligation, la question est : quel instrument le dit ?</p>');

